const workdir = "/private/tmp/task-harness-portability-u3tqwccr/p3_56_resume-negative";
const readbackInput = {
  cmd: "sed -n '1,260p' evidence/T3-assessment.md",
  workdir,
  yield_time_ms: 10000,
  max_output_tokens: 30000
};
const readbackResult = await tools.exec_command(readbackInput);

const hasMissingVersionNo =
  readbackResult.output.includes("Attributable source/artifact version is missing") &&
  readbackResult.output.includes("**No**");
const hasMissingExitNo =
  readbackResult.output.includes("Individual checked command's final exit status is missing") &&
  readbackResult.output.includes("**No**");
const separatesDecisions =
  readbackResult.output.includes("T3 assessment task completion") &&
  readbackResult.output.includes("Assessed incomplete evidence") &&
  readbackResult.output.includes("Overall run or Skill pass");
const warnsLowLevel =
  readbackResult.output.includes("low-level tool exit 0") &&
  readbackResult.output.includes("not established");

const json = value => JSON.stringify(value, null, 2);
const receipt = [
  "# Native readback receipt: T3 / A1 / attempt 1",
  "",
  "Purpose: verify that the independent assessment artifact exists and contains both required negative evidence-sufficiency verdicts and the task/subject/overall distinction.",
  "",
  "This low-level readback result is not an overall Task Harness or Skill pass.",
  "",
  "## Original tool input",
  "",
  "```json",
  json(readbackInput),
  "```",
  "",
  "## Original tool result",
  "",
  "```json",
  json(readbackResult),
  "```",
  "",
  "## Mechanical content checks",
  "",
  `Missing-version case has a No verdict: ${hasMissingVersionNo ? "yes" : "no"}`,
  `Missing-final-exit case has a No verdict: ${hasMissingExitNo ? "yes" : "no"}`,
  `Task completion, assessed-object pass, and overall Skill/run are separated: ${separatesDecisions ? "yes" : "no"}`,
  `Artifact explicitly rejects treating low-level exit 0 as overall pass: ${warnsLowLevel ? "yes" : "no"}`,
  ""
].join("\n");

const patchBody = receipt.split("\n").map(line => "+" + line).join("\n");
const patch = `*** Begin Patch\n*** Add File: ${workdir}/evidence/T3-readback-1.md\n${patchBody}\n*** End Patch`;
const writeResult = await tools.apply_patch(patch);

text(JSON.stringify({
  readback_exit_code: readbackResult.exit_code,
  missing_version_no: hasMissingVersionNo,
  missing_final_exit_no: hasMissingExitNo,
  decisions_separated: separatesDecisions,
  rejects_low_level_as_overall_pass: warnsLowLevel,
  receipt_write_result: writeResult
}));

